mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.8, -3.0);
  vec3 rd = normalize(vec3(p, 1.5));
  rd.yz = rot(-0.25) * rd.yz;
  vec3 col = vec3(0.01, 0.01, 0.02);
  vec3 pos = ro;
  float diskGlow = 0.0;
  for (int i = 0; i < 48; i++) {
    float r = length(pos);
    if (r < 0.65) { col = vec3(0.0); break; }
    vec3 force = -normalize(pos) / (r * r * 0.75);
    rd = normalize(rd + force * 0.08);
    pos += rd * 0.12;
    if (abs(pos.y) < 0.18 && r > 0.85 && r < 2.6) {
      float dens = (1.0 - abs(pos.y) / 0.18) * (1.0 - (r - 0.85) / 1.75);
      float swirl = sin(atan(pos.z, pos.x) * 4.0 - r * 8.0 + time * 4.0);
      diskGlow += dens * (0.8 + 0.4 * swirl) * 0.25;
    }
  }
  col += diskGlow * vec3(1.3, 0.55, 0.08) * (1.0 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
